package es.scafftrix.factory.domain;

/**
 * Technical profile of a project that can be generated by the factory.
 *
 * <p>The enum is intentionally open: adding a new profile (microservice, scheduled job, ...)
 * requires only a new constant plus the corresponding {@code ProjectProfileStrategy}
 * implementation. No other layer needs to change.
 */
public enum ProjectType {

    /** Minimal server-rendered Spring Boot monolith: contract first, MapStruct and H2. */
    SPRING_BOOT("Monolito Spring Boot", "Monolito Spring Boot mínimo: OpenAPI, MapStruct, H2 y schema.sql/data.sql",
            java.util.EnumSet.of(DatabaseType.H2, DatabaseType.POSTGRESQL),
            TechnologyManifest.maven("H2", "Thymeleaf", true, ConfigFormat.PROPERTIES,
                    "Capa web Thymeleaf y contrato OpenAPI: el stack fijo de un monolito contract-first.")),

    /**
     * Standalone Spring Batch process: CSV in, JDBC out, no web layer.
     *
     * <p>There is a single Spring Batch profile on purpose. An earlier revision also exposed
     * {@code SPRING_BATCH_PROCESS} next to a JHipster-based {@code SPRING_BATCH}, which made the
     * dropdown offer two options for the same thing. The batch profile is now produced by
     * {@code TemplateProjectGenerator} from {@code project-batch-template}: a real process with
     * reader, processor, writer, listener and error handling, rather than a web application that
     * merely carries batch scaffolding.
     */
    SPRING_BATCH("Spring Batch",
            "Proceso Spring Batch autónomo: lector CSV, procesador con filtrado, writer JDBC y H2 embebida",
            java.util.EnumSet.of(DatabaseType.H2),
            TechnologyManifest.maven("H2", "", false, ConfigFormat.PROPERTIES,
                    "Proceso autónomo sin capa web: no hay Thymeleaf ni contrato OpenAPI.")),

    /**
     * Contract-first Spring Boot microservice: the OpenAPI contract drives the HTTP layer,
     * the code is split into api/application/domain/infrastructure and persistence is
     * modelled as a port with a JPA adapter.
     *
     * <p>It supports both the in-memory database used for local development and tests and
     * PostgreSQL, which is the database the generated {@code docker-compose.yml} starts.
     */
    SPRING_MICROSERVICE("Microservicio Spring Boot",
            "Microservicio Spring Boot contract-first: OpenAPI, MapStruct, JPA/Flyway, "
                    + "arquitectura api/application/domain/infrastructure y Docker",
            java.util.EnumSet.of(DatabaseType.H2, DatabaseType.POSTGRESQL),
            TechnologyManifest.maven("H2 (dev) / PostgreSQL (prod)", "", true, ConfigFormat.YAML,
                    "API REST contract-first: H2 en memoria en desarrollo y PostgreSQL 16 en despliegue."));

    private final String displayName;
    private final String description;
    private final java.util.Set<DatabaseType> allowedDatabases;
    private final TechnologyManifest manifest;

    ProjectType(String displayName, String description, java.util.Set<DatabaseType> allowedDatabases,
                TechnologyManifest manifest) {
        this.displayName = displayName;
        this.description = description;
        this.allowedDatabases = java.util.Set.copyOf(allowedDatabases);
        this.manifest = manifest;
    }

    public String getDisplayName() {
        return displayName;
    }

    public String getDescription() {
        return description;
    }

    public java.util.Set<DatabaseType> getAllowedDatabases() {
        return allowedDatabases;
    }

    public boolean supports(DatabaseType databaseType) {
        return databaseType != null && allowedDatabases.contains(databaseType);
    }

    /** The pinned stack this profile really uses, stored on the project at creation time. */
    public TechnologyStack technologyStack() {
        return manifest.toTechnologyStack();
    }

    public boolean isContractFirst() {
        return manifest.contractFirst();
    }

    /** Configuration format chosen by default for this profile. */
    public ConfigFormat defaultConfigFormat() {
        return manifest.configFormat();
    }

    public String getDatabaseLabel() {
        return manifest.database();
    }

    /** May be blank when the profile has no view layer. */
    public String getFrontendLabel() {
        return manifest.frontend();
    }

    public String getBuildToolLabel() {
        return manifest.buildTool();
    }

    /** One sentence explaining what the stack means for the profile, shown under the panel. */
    public String getTechnologyNote() {
        return manifest.note();
    }
}